<script setup>
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, thumb } from '../api'
import DesignFields from '../components/DesignFields.vue'
import TagPicker from '../components/TagPicker.vue'
const VersionPanel=defineAsyncComponent(()=>import('../components/VersionPanel.vue'))
const route=useRoute()
const page=ref({items:[],total:0}),q=ref(''),world=ref(''),favorite=ref(false),tag=ref(''),tags=ref([]),offset=ref(0)
const choiceQ=ref(''),worlds=ref([]),works=ref([]),characters=ref([]),profile=ref(null),form=ref(null),baseline=ref(''),tab=ref('design'),lookId=ref('')
const creating=ref(false),createForm=ref({title:'',character_id:'',world_id:'',work_id:''}),error=ref(''),busy=ref(false),pendingId=ref(null),publishConfirm=ref(false)
const picker=ref(false),refKind=ref('asset'),refRole=ref('reference'),allowCross=ref(false),pool=ref({items:[],total:0}),poolQ=ref(''),poolOffset=ref(0),refsOffset=ref(0)
let disposed=false,sequence=0,timer
onBeforeUnmount(()=>{disposed=true;sequence++;clearTimeout(timer)})
const body=()=>form.value?{...form.value,tag_ids:[...form.value.tag_ids]}:null
const dirty=computed(()=>form.value&&JSON.stringify(body())!==baseline.value)
const look=computed(()=>form.value?.designs.find(d=>d.id===lookId.value))
const visibleRefs=computed(()=>profile.value?.references.slice(refsOffset.value,refsOffset.value+50)||[])
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=false}}
async function load(){const n=++sequence;const data=await api.get('/api/oc',{q:q.value,world_id:world.value,favorite:favorite.value,tag:tag.value,offset:offset.value,limit:50});if(!disposed&&n===sequence)page.value=data}
watch([q,world,favorite,tag],()=>{offset.value=0;clearTimeout(timer);timer=setTimeout(()=>load().catch(e=>{error.value=e.message}),200)})
function bind(data){if(disposed)return;profile.value=data;form.value=Object.fromEntries(['title','fields','designs','source','favorite','stars','preference','notes'].map(k=>[k,structuredClone(data[k])]));form.value.tag_ids=data.tags.map(t=>t.id);baseline.value=JSON.stringify(body());refsOffset.value=0;publishConfirm.value=false;if(!form.value.designs.some(d=>d.id===lookId.value))lookId.value=form.value.designs[0]?.id||''}
async function select(id,discard=false){if(dirty.value&&!discard){pendingId.value=id;return}bind(await api.get(`/api/oc/${id}`));pendingId.value=null;creating.value=false}
onMounted(()=>run(async()=>{const [w,c,k,t]=await Promise.all([api.get('/api/oc/choices',{kind:'world'}),api.get('/api/oc/choices',{kind:'character'}),api.get('/api/oc/choices',{kind:'work'}),api.get('/api/tags',{limit:500})]);if(disposed)return;worlds.value=w.items;characters.value=c.items;works.value=k.items;tags.value=t.items;await load();const id=Number(route.query.id)||page.value.items[0]?.id;if(id)await select(id)}))
async function searchChoices(){const [w,c,k]=await Promise.all(['world','character','work'].map(kind=>api.get('/api/oc/choices',{kind,q:choiceQ.value})));worlds.value=w.items;characters.value=c.items;works.value=k.items}
async function create(){const data=await api.post('/api/oc',{title:createForm.value.title,character_id:createForm.value.character_id?Number(createForm.value.character_id):null,world_id:createForm.value.character_id?null:createForm.value.world_id||null,work_id:createForm.value.character_id?null:createForm.value.work_id||null});bind(data);creating.value=false;await load()}
async function save(){bind(await api.put(`/api/oc/${profile.value.id}`,{...body(),expected_version:profile.value.version}));await load();if(pendingId.value)await select(pendingId.value,true)}
function newLook(){const d={id:crypto.randomUUID().replaceAll('-',''),name:'新造型',fields:{},notes:''};form.value.designs.push(d);lookId.value=d.id}
function copyLook(){if(!look.value)return;const d={...structuredClone(look.value),id:crypto.randomUUID().replaceAll('-',''),name:look.value.name+' · 副本'};form.value.designs.push(d);lookId.value=d.id}
function removeLook(){form.value.designs=form.value.designs.filter(d=>d.id!==lookId.value);lookId.value=form.value.designs[0]?.id||''}
function worldName(id){return worlds.value.find(w=>w.id===id)?.name||'独立角色'}
async function loadPool(){const paths={asset:'assets',note:'notes',model:'sd-models',prompt:'prompts'};const data=await api.get('/api/'+paths[refKind.value],{q:poolQ.value,limit:50,offset:poolOffset.value});if(!disposed)pool.value=data}
async function openPicker(){picker.value=!picker.value;if(picker.value)await loadPool()}
async function addRef(row,asCover=false){bind(await api.post(`/api/oc/${profile.value.id}/references`,{kind:refKind.value,entity_id:row.id,role:refRole.value,design_id:lookId.value||null,allow_cross_world:allowCross.value,as_cover:asCover,expected_version:profile.value.version}));await load()}
async function removeRef(row){bind(await api.del(`/api/oc/${profile.value.id}/references/${row.id}?expected_version=${profile.value.version}`));await load()}
function refLink(r){return {asset:`/assets?open=${r.entity_id}`,note:`/notes/${r.entity_id}`,prompt:`/prompts?id=${r.entity_id}`,model:`/models?id=${r.entity_id}`}[r.kind]}
async function publish(){await api.post(`/api/oc/${profile.value.id}/publish`,{expected_version:profile.value.version,confirmed:publishConfirm.value});bind(await api.get(`/api/oc/${profile.value.id}`))}
</script>
<template><div class="grid">
<p v-if="error" role="alert" class="notice">{{error}}</p>
<p v-if="dirty" role="status" class="notice">草稿有未保存修改。请先保存，再引用资料或发布到百科。</p>
<p v-if="pendingId" class="notice">切换前处理当前草稿：<button :disabled="busy" @click="run(save)">保存并打开</button><button :disabled="busy" @click="run(()=>select(pendingId,true))">放弃未保存修改并打开</button><button @click="pendingId=null">取消切换</button></p>
<div class="oc-layout">
<aside class="card grid oc-list"><div class="row"><b>原创角色</b><button :disabled="busy||dirty" @click="creating=true">新建OC / 关联百科</button></div><label class="field">搜索角色与设计<input v-model="q" placeholder="名称、字段、造型、备注"/></label><label class="field">世界观范围<select v-model="world"><option value="">全部世界观</option><option value="none">独立角色</option><option v-for="w in worlds" :key="w.id" :value="w.id">{{w.name}} · #{{w.id}}</option></select></label><select v-model="tag" aria-label="OC标签筛选"><option value="">全部标签</option><option v-for="t in tags" :key="t.id" :value="t.id">{{t.name}}</option></select><label class="row"><input v-model="favorite" type="checkbox"/>仅收藏</label>
<div class="profile-list"><button v-for="p in page.items" :key="p.id" class="profile-row" :class="{active:profile?.id===p.id}" :disabled="busy" @click="run(()=>select(p.id))"><img v-if="p.cover_asset_id" :src="thumb(p.cover_asset_id)" :alt="p.title+'封面'" loading="lazy"/><span v-else class="monogram">{{p.title.slice(0,1)}}</span><span><b>{{p.title}}</b><small>{{worldName(p.world_id)}} · {{p.stars}}星 · {{p.preference}}</small><small>{{p.tags.map(t=>t.name).join(' · ')}}</small></span></button><p v-if="!page.items.length" class="empty">暂无档案。可新建独立OC，或关联已有百科角色。</p></div><nav class="row"><button :disabled="busy||!offset" @click="offset-=50;run(load)">上一页</button><span>{{page.total}}个</span><button :disabled="busy||offset+50>=page.total" @click="offset+=50;run(load)">下一页</button></nav></aside>
<section class="grid oc-main">
<section v-if="creating" class="card grid"><h2>建立创作档案</h2><form class="row" @submit.prevent="run(searchChoices)"><input v-model="choiceQ" aria-label="搜索世界观角色作品" placeholder="查找已有世界观、角色或作品（最多100项）"/><button>查找归属</button></form><label class="field">档案标题<input v-model="createForm.title" maxlength="200"/></label><label class="field">百科角色<select v-model="createForm.character_id"><option value="">新建角色</option><option v-for="c in characters" :key="c.id" :value="c.id">{{c.name}} · #{{c.id}} · {{worldName(c.world_id)}}</option></select></label><div v-if="!createForm.character_id" class="grid cols-2"><label class="field">世界观（可留空）<select v-model="createForm.world_id"><option value="">独立角色</option><option v-for="w in worlds" :key="w.id" :value="w.id">{{w.name}} · #{{w.id}}</option></select></label><label class="field">作品（可留空）<select v-model="createForm.work_id"><option value="">未指定</option><option v-for="w in works" :key="w.id" :value="w.id">{{w.name}}</option></select></label></div><p class="small muted">关联已有角色时继承其稳定ID和归属；不复制或覆盖正式设定。新建时自动保留草稿版本。</p><div class="row"><button class="primary" :disabled="busy||!createForm.title.trim()" @click="run(create)">创建创作档案</button><button @click="creating=false">取消</button></div></section>
<template v-if="profile && form">
<header class="card row"><div><h2>{{profile.title}}</h2><span class="muted small">{{worldName(profile.world_id)}} · 档案 #{{profile.id}} · 版本 #{{profile.version}}</span></div><span class="spacer"/><button class="primary" :disabled="busy||!dirty" @click="run(save)">保存设计</button><RouterLink v-if="profile.character_id" class="btn" :to="`/characters/${profile.character_id}`">百科角色</RouterLink><RouterLink v-if="profile.world_id" class="btn" :to="`/worlds?id=${profile.world_id}`">世界观</RouterLink></header>
<p v-if="profile.character_missing" class="notice">原百科角色已删除；创作草稿保留，未关联复用ID的新角色。</p>
<nav class="row"><button v-for="[k,label] in [['design','角色设计'],['looks','服装与造型'],['references','素材关联'],['versions','版本历史']]" :key="k" :class="{primary:tab===k}" @click="tab=k">{{label}}</button></nav>
<section v-if="tab==='design'" class="card grid"><div class="grid cols-2"><label class="field">档案标题<input v-model="form.title" maxlength="200"/></label><label class="field">来源与许可说明<input v-model="form.source" maxlength="2000"/></label></div><DesignFields v-model="form.fields" prefix="角色"/><div class="grid cols-2"><label class="row"><input v-model="form.favorite" type="checkbox"/>收藏</label><label class="field">星级<input v-model.number="form.stars" type="number" min="0" max="5"/></label><label class="field">喜爱度（0–100）<input v-model.number="form.preference" type="number" min="0" max="100"/></label></div><TagPicker v-model="form.tag_ids"/><label class="field">创作备注<textarea v-model="form.notes" maxlength="30000"/></label><details><summary>正式百科设定（只读）</summary><pre>{{profile.canonical_profile||'尚无正式设定；草稿不会自动覆盖百科。'}}</pre></details><label class="row"><input v-model="publishConfirm" type="checkbox"/>明确将已保存字段补充到百科，保留已有正文并创建版本</label><button :disabled="busy||dirty||!publishConfirm||!profile.character_id" @click="run(publish)">补充到角色百科</button></section>
<section v-else-if="tab==='looks'" class="card grid"><div class="row"><select v-model="lookId" aria-label="当前造型"><option value="">默认角色方案</option><option v-for="d in form.designs" :key="d.id" :value="d.id">{{d.name}}</option></select><button @click="newLook">新造型</button><button :disabled="!look" @click="copyLook">复制造型</button></div><template v-if="look"><label class="field">造型名称<input v-model="look.name" maxlength="100"/></label><DesignFields v-model="look.fields" prefix="造型" :defaults="['服装','配饰','发型','背景','外观修改']"/><label class="field">造型说明<textarea v-model="look.notes" maxlength="10000"/></label><button @click="removeLook">从当前草稿移除此造型（不删素材）</button></template><p v-else class="empty">每个造型有稳定ID，可保存不同服装、外观与背景。先保存，再关联素材。</p></section>
<section v-else-if="tab==='references'" class="card grid"><div class="row"><h2>共享素材与创作资料</h2><span class="spacer"/><button :disabled="busy" @click="run(openPicker)">{{picker?'收起选择':'从资料库选择'}}</button></div><p class="small muted">引用现有素材、笔记、提示词和模型档案，不复制原文件。素材引用会记录当前版本；原地索引不会悄悄复制原件。</p>
<section v-if="picker" class="grid"><div class="grid cols-2"><label class="field">资料类型<select v-model="refKind" @change="poolOffset=0;run(loadPool)"><option value="asset">图片 / 绘画工程 / 其他素材</option><option value="note">设定笔记</option><option value="prompt">提示词</option><option value="model">模型档案</option></select></label><label class="field">用途<select v-model="refRole"><option value="reference">参考资料</option><option value="portrait">角色立绘</option><option value="painting-project">绘画工程</option><option value="clothing">服装参考</option><option value="expression">表情参考</option></select></label></div><form class="row" @submit.prevent="poolOffset=0;run(loadPool)"><input v-model="poolQ" aria-label="搜索引用资料" placeholder="按标题搜索"/><button :disabled="busy">搜索资料</button></form><label class="field">关联造型<select v-model="lookId"><option value="">默认角色方案</option><option v-for="d in form.designs" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="row"><input v-model="allowCross" type="checkbox"/>明确允许本次跨世界观引用</label><div class="resource-pool"><article v-for="a in pool.items" :key="a.id" class="resource-row"><img v-if="refKind==='asset' && a.width" :src="thumb(a.id)" :alt="a.title" loading="lazy"/><div><b>{{a.title||a.name}}</b><small>#{{a.id}} · {{a.kind}}</small></div><button :disabled="busy||dirty" @click="run(()=>addRef(a))">引用</button><button v-if="refKind==='asset' && a.width" :disabled="busy||dirty" @click="run(()=>addRef(a,true))">引用并设封面</button></article></div><nav class="row"><button :disabled="busy||!poolOffset" @click="poolOffset-=50;run(loadPool)">上一页资料</button><span>{{pool.total}}项</span><button :disabled="busy||poolOffset+50>=pool.total" @click="poolOffset+=50;run(loadPool)">下一页资料</button></nav></section>
<article v-for="r in visibleRefs" :key="r.id" class="resource-row card"><img v-if="r.kind==='asset' && r.is_image && r.status==='ok' && !r.historical_file" :src="thumb(r.entity_id)" :alt="r.title" loading="lazy"/><div><b>{{r.title}}</b><small>{{r.kind}} · {{r.role}} · {{form.designs.find(d=>d.id===r.design_id)?.name || (r.missing_design?'已归档造型':'默认方案')}}</small><p v-if="r.status!=='ok'" class="notice">{{r.status}}</p><small v-if="r.historical_file">素材已更新；引用时版本 #{{r.asset_version}} 保留，请在素材历史查看。</small></div><RouterLink v-if="r.status==='ok'" class="btn" :to="refLink(r)">打开资料</RouterLink><button :disabled="busy||dirty" @click="run(()=>removeRef(r))">移除引用</button></article><nav class="row"><button :disabled="!refsOffset" @click="refsOffset-=50">前50项</button><span>{{profile.references.length}}个引用</span><button :disabled="refsOffset+50>=profile.references.length" @click="refsOffset+=50">后50项</button></nav></section>
<section v-else-if="tab==='versions'" class="card"><VersionPanel :key="profile.id" kind="oc" :entity-id="profile.id" @restored="run(()=>select(profile.id,true));load()"/></section>
<footer class="row small muted"><RouterLink to="/prompts">提示词库</RouterLink><RouterLink to="/models">Checkpoint / LoRA档案</RouterLink><RouterLink to="/assets">通用素材库</RouterLink><RouterLink to="/backups">备份与恢复</RouterLink></footer>
</template><div v-else-if="!creating" class="card empty">建立一个OC草稿开始创作。世界观可留空，无GPU也能管理设计和素材。</div>
</section></div></div></template>
<style scoped>
.oc-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:14px;align-items:start}.oc-layout>*{min-width:0}.oc-list{align-content:start;position:sticky;top:90px}.profile-list{display:grid;gap:6px;max-height:540px;overflow:auto}.profile-row{display:flex;gap:10px;align-items:center;text-align:left;white-space:normal;padding:9px}.profile-row.active{border-color:var(--accent);background:var(--panel2)}.profile-row img,.monogram{width:48px;height:58px;object-fit:cover;border-radius:7px;flex-shrink:0}.monogram{display:grid;place-items:center;background:var(--sunken);font-size:24px;color:var(--accent)}.profile-row small{display:block;font-size:11px;color:var(--muted)}h2{margin:0}.row input[type=checkbox]{width:auto}.resource-pool{max-height:440px;overflow:auto}.resource-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px}.resource-row>div{flex:1;min-width:100px;overflow-wrap:anywhere}.resource-row img{width:60px;height:70px;object-fit:contain;background:var(--sunken)}.resource-row small{display:block;color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;font-size:12px}@media(max-width:1000px){.oc-layout{grid-template-columns:minmax(0,1fr)}.oc-list{position:static}.profile-list{max-height:240px}}.field{min-width:0}
</style>
